import{_ as t,o as a,c as i,a0 as r}from"./chunks/framework.CShDTZbC.js";const u=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/overview.md","filePath":"getting-started/overview.md"}'),n={name:"getting-started/overview.md"};function s(o,e,l,c,h,g){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>Cognimemo is a persistent memory service for AI agents. It provides three core operations:</p><ul><li><strong>Retain</strong> — Store memories (text, files, URLs)</li><li><strong>Recall</strong> — Retrieve memories via semantic search</li><li><strong>Reflect</strong> — Generate insights from accumulated memories</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client (SDK/MCP/Web) → Gateway (auth, quotas, billing) → Engine (memory storage, embeddings, graph)</span></span></code></pre></div><ul><li><strong>Gateway</strong> — API key auth, rate limiting, quota enforcement, Stripe billing</li><li><strong>Engine</strong> — Per-org Postgres schemas, vector embeddings, entity graphs</li><li><strong>Web</strong> — Next.js dashboard for managing keys, viewing usage, billing</li></ul><h2 id="multi-tenancy" tabindex="-1">Multi-tenancy <a class="header-anchor" href="#multi-tenancy" aria-label="Permalink to &quot;Multi-tenancy&quot;">​</a></h2><p>Each organization gets an isolated Postgres schema. API keys are scoped to an org and can be restricted by operation type.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Cognimemo supports:</p><ul><li>Google SSO via WorkOS</li><li>Email + password via WorkOS</li><li>API keys for SDK/MCP access</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/getting-started/quickstart.html">Quickstart</a></li><li><a href="/getting-started/authentication.html">Authentication</a></li><li><a href="/mcp/overview.html">MCP Server</a></li></ul>',13)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
